/**
 * Fork: the web app has a tab icon and a home-screen icon (the default
 * LearnHarness icon, generated by scripts/make-icons.mjs into app/).
 */
import { expect, test } from "@playwright/test";

test("@desktop the page links the LearnHarness icons and they load", async ({ page, request }) => {
	await page.goto("/");
	const links = await page.locator('head link[rel="icon"], head link[rel="apple-touch-icon"]').evaluateAll((els) =>
		els.map((el) => ({ rel: el.getAttribute("rel"), href: el.getAttribute("href"), type: el.getAttribute("type") })));
	expect(links.filter((l) => l.rel === "icon").length, "a tab icon").toBeGreaterThan(0);
	expect(links.some((l) => l.rel === "apple-touch-icon"), "a home-screen icon").toBe(true);
	expect(links.some((l) => l.type === "image/svg+xml"), "the vector icon").toBe(true);
	for (const link of links) {
		const response = await request.get(link.href!);
		expect(response.status(), link.href!).toBe(200);
		expect((await response.body()).length, link.href!).toBeGreaterThan(100);
	}
	const ico = await request.get("/favicon.ico");
	expect(ico.status()).toBe(200);
	expect(ico.headers()["content-type"]).toContain("icon");
});
